CREATE Proc [dbo].[GetMainKitchenAutoDemandSheetByDept] @BRId as int, @DId as int as Select i.ItemId,i.Item,u.Unit,u.UId, isnull( ipl.Parlevel -  (Select  ( Select isnull(Sum(Qty),0) from WareHouse_Branch where [Type]='In' and ItemId=i.ItemId and BRId=@BRId and Did = @DId)  - ( Select isnull(Sum(Qty),0) from WareHouse_Branch where [Type]='Out' and ItemId=i.ItemId  and BRId=@BRId and Did = @DId )),0) as DemandQty From Item i  inner join ItemParLevel ipl on i.ItemId=ipl.ItemId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join Unit u on iu.IssUnit=u.Uid  where ipl.BRId=@BRId and ipl.SId=0  and sc.SubCategory<>'Sub Recipe' and ipl.DId = @DId and ipl.Parlevel > 0 group by i.ItemId,i.Item,u.Unit,u.UId,ipl.Parlevel order by i.Item